257	/// Clip ▸ Switch Angle ▸ (road map "creator-jobs" SW1, spec §11 SW-13…SW-15):
258	/// the one selected clip re-picked from the chosen covering track by
259	/// `SwitchAngle.plan`, as one undo step through `applyEdit`, then the new
260	/// pieces selected. A plan's refusal beeps and reaches the inspector's
261	/// refusal strip. `switch_angle`'s tool mirrors it (`AgentServer+Switch.swift`).
262	/// The rows are `SwitchAngleMenuFiller`'s (`AppDelegate+ClipMenus.swift`).
263	extension EditorViewController {
264	
265	    /// The one selected clip when the menu may re-pick it: exactly one clip
266	    /// selected, its track unlocked, no link (SW-15 (b)).
267	    var switchAngleClip: ClipSnapshot? {
268	        guard let document, selectedClips.count == 1, let clip = selectedClips.first,
269	            clip.linked == nil,
270	            document.editedProject.snapshot.track(clip.track)?.locked == false
271	        else { return nil }
272	        return clip
273	    }
274	
275	    @objc func switchAngle(_ sender: Any?) {
276	        guard let document, view.window?.attachedSheet == nil,
277	            let track = ((sender as? NSMenuItem)?.representedObject as? NSNumber)?.uint32Value,
278	            let clip = switchAngleClip
279	        else {
280	            NSSound.beep()
281	            return
282	        }
283	        let answer: SwitchAngle.Answer
284	        do {
285	            answer = try SwitchAngle.plan(
286	                clip: clip.id, angle: track, in: document.editedProject)
287	        } catch {
288	            NSSound.beep()
289	            return
290	        }
291	        switch answer {
292	        case .plan(let plan):
293	            document.applyEdit(plan.actionName, plan.ops)
294	            document.selection = Set(plan.pieces)
295	        case .refused(let reason):
296	            NSSound.beep()
297	            NotificationCenter.default.post(
298	                name: .projectDocumentDidRefuse, object: document,
299	                userInfo: ["refusal": ReelRefusal(op: "switch_angle", reason: reason)])
300	        }
301	    }
302	
303	    /// The menu arm, answered from `validateUserInterfaceItem`'s default case;
304	    /// nil for any other action. On when `switchAngleClip` exists, the item's
305	    /// track is still one of its angles and no sheet is up; allowed inside a
306	    /// nest.
307	    func validateSwitchAngleAction(
308	        _ action: Selector, item: any NSValidatedUserInterfaceItem
309	    ) -> Bool? {
310	        guard action == #selector(switchAngle(_:)) else { return nil }
311	        guard let document, view.window?.attachedSheet == nil, let clip = switchAngleClip,
312	            let track = ((item as? NSMenuItem)?.representedObject as? NSNumber)?.uint32Value
313	        else { return false }
314	        return SwitchAngle.angles(for: clip, in: document.editedProject.snapshot)
315	            .contains { $0.track == track }
316	    }
317	}
318	final class SwitchAngleMenuFiller: NSObject, NSMenuDelegate {
319	    static let shared = SwitchAngleMenuFiller()
320	
321	    /// "No Covering Angle": `switchAngle(_:)` with no track, which its
322	    /// validator always turns off. It carries the action so the menu's
323	    /// selector is a live leaf before any project opens (the menu's
324	    /// three-way check, `v2_menu.py` H1).
325	    static func placeholder() -> NSMenuItem {
326	        NSMenuItem(
327	            title: "No Covering Angle",
328	            action: #selector(EditorViewController.switchAngle(_:)), keyEquivalent: "")
329	    }
330	
331	    func menuNeedsUpdate(_ menu: NSMenu) {
332	        fill(menu, for: NSApp.mainWindow)
333	    }
334	
335	    func fill(_ menu: NSMenu, for window: NSWindow?) {
336	        let editor = window?.contentViewController as? EditorViewController
337	        var angles: [SwitchAngle.Angle] = []
338	        if let editor, let document = editor.document, editor.selectedClips.count == 1,
339	            let clip = editor.selectedClips.first
340	        {
341	            angles = SwitchAngle.angles(for: clip, in: document.editedProject.snapshot)
342	        }
343	        menu.removeAllItems()
344	        guard !angles.isEmpty else {
345	            menu.addItem(Self.placeholder())
346	            return
347	        }
348	        for (index, angle) in angles.enumerated() {
349	            let item = NSMenuItem(
350	                title: angle.title,
351	                action: #selector(EditorViewController.switchAngle(_:)), keyEquivalent: "")
352	            item.tag = index
353	            item.representedObject = NSNumber(value: angle.track)
354	            menu.addItem(item)
355	        }
356	    }
357	}
