360	/// The catalog rows of `copy_pieces` and `switch_angle` (road map
361	/// "creator-jobs" SW1, spec §11 SW-11…SW-15), spliced in last by
362	/// `creatorTools()`, after `switch_layout`'s.
363	extension AgentServer {
364	
365	    func switchTools() -> [[String: Any]] {
366	        let ticks = "in TICKS — 600000 per second, so 1 s = 600000 and one 30 fps frame = 20000"
367	        return [
368	            // The primitive Clip ▸ Switch Angle ▸ (`switchAngle` in
369	            // EditorViewController+SwitchAngle.swift) writes with: one per
370	            // angle clip the shot's span crosses.
371	            opTool(
372	                "copy_pieces",
373	                "Copies pieces of a clip onto another track at the same project times — the "
374	                    + "op Clip ▸ Switch Angle ▸ writes with. Each piece is exactly what two "
375	                    + "splits at its range's ends would leave in the middle: the same source "
376	                    + "frames at the same times (speed, a ramp, reversal, a graphic's own "
377	                    + "timeline, timed words and actions cut as split cuts them), so a piece "
378	                    + "of a synced camera angle shows that angle's own frame at every time. "
379	                    + "Pieces get fresh ids, no transition and no link. One undo step, \"Copy "
380	                    + "Pieces\". Each range's ends are snapped to the frame grid and a reversed "
381	                    + "pair is the same range; a range empty on the grid is skipped. Refused, "
382	                    + "nothing changed, in this order: a nest clip, a range outside the clip, "
383	                    + "two ranges that overlap (touching is fine), a locked destination, and a "
384	                    + "destination holding a clip over a range (naming that clip and its ends). "
385	                    + "Inside a nest (scope) the times and tracks are the nest's.",
386	                [
387	                    "clip": "The clip to copy pieces of.",
388	                    "track": "The track the pieces land on; it must be free over every range.",
389	                    "ranges": "[[from, to], …] project times, \(ticks), inside the clip and "
390	                        + "not overlapping. At least one pair.",
391	                    "video": "Set each piece's picture on (true) or off (false). Default: the "
392	                        + "clip's own.",
393	                    "audio": "Set each piece's sound on (true) or off (false). Default: the "
394	                        + "clip's own.",
395	                ]),
396	            // It mirrors Clip ▸ Switch Angle ▸ (`switchAngle` in
397	            // EditorViewController+SwitchAngle.swift), through the same planner
398	            // (SwitchAngle.swift). An app-state composite of ordinary ops: no
399	            // `scope`, one undo step.
400	            tool(
401	                "switch_angle",
402	                "Re-picks one shot from another camera angle — the mirror of Clip ▸ Switch "
403	                    + "Angle ▸. An angle is a TRACK whose video clips (media with a picture; a "
404	                    + "clip with its picture off or on a hidden track still counts) cover the "
405	                    + "shot's whole span. The shot is deleted and the angle copied over the same "
406	                    + "span with copy_pieces, one piece per angle clip the span crosses (where "
407	                    + "two angle clips overlap, the later one takes over at its own start), "
408	                    + "each with the shot's video and audio switches; the clips either side are "
409	                    + "trimmed back to their old edges, so a dissolve on either edge is re-formed "
410	                    + "with its kind, curve and audio shape. The shot's grade, punch-in, actions "
411	                    + "and other settings do NOT carry. One undo step, \"Switch Angle\", or "
412	                    + "\"Switch Angle (transition removed)\" when an edge's dissolve could not be "
413	                    + "re-formed against a short piece and was dropped. Works in the container "
414	                    + "set_scope has open. Answers {ok, step, pieces (the new clip ids in time "
415	                    + "order), transitions_removed (0–2), project}. Refused, nothing changed: "
416	                    + "the angle is the shot's own track, the shot's track is locked, the shot "
417	                    + "is linked (Detach Audio's pair), the angle does not cover the shot "
418	                    + "(naming the first uncovered tick), or a step of the sequence is refused "
419	                    + "or an edge is held short by a speed ramp (in its own sentence).",
420	                [
421	                    "clip": [
422	                        "type": "integer",
423	                        "description": "The shot to re-pick: a clip on the program track.",
424	                    ],
425	                    "angle": [
426	                        "type": "integer",
427	                        "description": "The id of the track to re-pick it from.",
428	                    ],
429	                ], required: ["clip", "angle"]),
430	            // It mirrors Clip ▸ Switch by Speaker… (`showSwitchBySpeakerSheet` in
431	            // EditorViewController+SwitchSpeaker.swift, the sheet
432	            // SwitchSpeakerSheetController), through the same SpeakerSwitch.read, plan and
433	            // edit (SW-23, SW-26). An app-state composite of ordinary ops: no `scope`, one
434	            // undo step.
435	            tool(
436	                "switch_by_speaker",
437	                "Cuts a Program track from synced cameras, showing whoever talks on each "
438	                    + "microphone — the mirror of Clip ▸ Switch by Speaker…. Run sync_audio first: "
439	                    + "it trusts the clips' placement. It reads the SELECTED clips (set_selection): "
440	                    + "an angle is a track holding a selected video clip; by default the "
441	                    + "microphones are the tracks holding a selected sound-only clip, else each "
442	                    + "camera is its own, paired front to back, and the one angle no speaker uses "
443	                    + "is the wide. The range is from/to, else the In–Out range, else the selected "
444	                    + "angle clips' extent. It reads each microphone's loudness and speech caches "
445	                    + "(made at import; a pending one is refused as still being analysed) and "
446	                    + "cuts a shot `lead` before each new speaker's turn, holds through short "
447	                    + "replies (min_turn) and silence, shows the wide during crosstalk and merges "
448	                    + "shots under min_shot. It writes, as ONE undo step \"Switch by Speaker\": a "
449	                    + "new track \"Program\" directly in front of the front-most angle (or, with "
450	                    + "track, that track cleared over the range), one copy_pieces per angle clip "
451	                    + "a shot crosses (picture on, sound off), the angle tracks hidden — or, "
452	                    + "when an angle track holds clips outside the range, its clips split at the "
453	                    + "range's ends with their pictures off inside — and, with mute_cameras, the "
454	                    + "cameras' own sound off inside the range (never on a microphone's track). "
455	                    + "Nothing outside the range changes and the microphones are never edited. "
456	                    + "Works in the container set_scope has open. ONE MICROPHONE FOR EVERYONE "
457	                    + "(the faces mode): when one microphone is shared by two or more angles — "
458	                    + "the default when the selection holds exactly one microphone — who talks "
459	                    + "is decided while the microphone hears speech by whose mouth moves most "
460	                    + "in each camera's on-device face analysis (the largest face; 1.5× the next "
461	                    + "camera's, else crosstalk); a named wide takes no part, and min_shot "
462	                    + "defaults to 3. Faces it still has to find are found first: the call "
463	                    + "waits up to 60 s, and past that is refused with what it covered kept — "
464	                    + "call again to continue. Answers {ok, applied, step "
465	                    + "(only when applied), track (the Program track; null when not applied and no "
466	                    + "track named), shots [{angle, start, end}], ops (the count), added (clips), "
467	                    + "speakers [{mic, angle}], wide, mute_cameras, mode (\"microphones\" or "
468	                    + "\"faces\"), note (in the faces mode: faces guess, check the cuts), "
469	                    + "project}. Refused, nothing "
470	                    + "changed, naming every reason at once: fewer than two angles or more than "
471	                    + "nine, a speaker without a microphone or an angle, one microphone for two "
472	                    + "speakers (outside the faces mode), a microphone still being analysed or "
473	                    + "with no speech, a camera whose faces are still being found or show no "
474	                    + "mouth that can be read, a faces analysis that failed, was stopped or did "
475	                    + "not finish within the wait, a project changed while it waited, a stretch "
476	                    + "no angle covers, more clips than the project may hold (raise min_shot), a "
477	                    + "track that cannot take the shots (locked, holding a selected clip, not in "
478	                    + "front of the angles, nothing in the range, or a clip that is not a piece "
479	                    + "of an angle), or an angle clip linked by Detach Audio (Attach Audio first).",
480	                [
481	                    "speakers": [
482	                        "type": "array", "minItems": 1,
483	                        "items": [
484	                            "type": "object",
485	                            "properties": [
486	                                "mic": ["type": "integer", "description": "The microphone's track id."],
487	                                "angle": [
488	                                    "type": "integer",
489	                                    "description": "The angle track that shows this person.",
490	                                ],
491	                            ],
492	                            "required": ["mic", "angle"],
493	                            "additionalProperties": false,
